import json,statistics,pathlib,shutil,hashlib,difflib
M=pathlib.Path('/opt/bench108');R=M/'results/python-opt-108';K=M/'src/kuasar-fork/kuasar-io/kuasar';B=M/'results/python-print-108'
measurements={}
for name,directory,log,key in [('baseline',B,None,'execute_rpc'),('readonly-cache',R/'readonly-cache',R/'readonly-cache.log','execute_rpc'),('stream',R/'stream',R/'stream.log','execute_stream')]:
 rows=[json.loads(p.read_text()) for p in directory.glob('*-kuasar-fork.json')];ids={x['sandbox_id'] for x in rows}
 if log:
  events=[json.loads(l[11:]) for l in log.read_text().splitlines() if l.startswith('E2B_TIMING ')]
 else:events=json.loads((R/'baseline-phases.json').read_text())
 guest=[x['guest'] for x in events if x.get('sid') in ids and x['stage']==key]
 assert len(rows)==len(guest)==10
 assert all(x['success'] and x['destroyed'] and x['attempts']==1 and x['marker']==x['received_marker'] for x in rows)
 measurements[name]={'comparison':json.loads((directory/'summary.json').read_text()),'create_median_ms':statistics.median(x['api_ms'] for x in rows),'command_to_print_median_ms':statistics.median(x['ready_ms']-x['api_ms'] for x in rows),'print_to_completion_median_ms':statistics.median(x['completion_ms']-x['ready_ms'] for x in rows),'guest_medians_us':{k:statistics.median(x[k] for x in guest) for k in guest[0] if k!='pid'},'all_success_destroyed_first_attempt':True}
prep=json.loads((R/'stream-preparation.json').read_text())['base'];ids={json.loads(p.read_text())['sandbox_id'] for p in (R/'stream').glob('*-kuasar-fork.json')}
ref=[json.loads(l) for l in (R/'stream-pool-events.jsonl').read_text().splitlines()];ref=[x for x in ref if x.get('retired_sid') in ids];assert len(ref)==10
refill={k:{'median_ms':statistics.median(x[k] for x in ref),'max_ms':max(x[k] for x in ref)} for k in ['elapsed_ms','replacement_ms']}
j=[json.loads(l) for l in (R/'stream-journal.jsonl').read_text().splitlines()];listen=[x for x in j if 'E2B compatible API listening' in str(x.get('MESSAGE',''))][-1];startup=(int(listen['__MONOTONIC_TIMESTAMP'])-int((R/'stream-start-us.txt').read_text()))/1000
validation={}
for n in ['validation','network-validation','tcp-validation','staging-validation','stream-validation','pristine']:
 validation[n]=json.loads((R/(n+'.json')).read_text());assert validation[n]['success']
resources={n:json.loads((R/(n+'.json')).read_text())['totals'] for n in ['stream-resources-before','stream-resources-after','final-resources']}
assert all(x['fds']==2239 for x in resources.values())
ready=json.loads((R/'final-ready.json').read_text());assert ready['ready']==64 and ready['assigned']==0
result={'runs':measurements,'preparation':prep,'service_startup_ms':startup,'refill':refill,'resources':resources,'validation':validation}
(R/'measurements.json').write_text(json.dumps(result,indent=2))
src=R/'source';src.mkdir(exist_ok=True);patch=[]
files=['integrations/e2b/exec_cache.py','integrations/e2b/image_pool.py','integrations/e2b/server.py','integrations/e2b/vm_rpc.py','integrations/e2b/test_exec_cache.py','integrations/e2b/test_vm_stream.py','integrations/e2b/test_server.py','vmm/task/src/util.rs','vmm/task/src/sandbox_service.rs','vmm/common/src/protos/sandbox.proto']
for f in files:
 p=K/f;shutil.copy2(p,src/p.name);before=R/'before'/p.name
 if before.exists():patch.extend(difflib.unified_diff(before.read_text().splitlines(True),p.read_text().splitlines(True),fromfile='before/'+f,tofile='after/'+f))
(R/'changes.patch').write_text(''.join(patch))
shutil.copy2(M/'deploy/fork/images.json',R/'images.json');shutil.copy2(M/'deploy/fork/config.toml',R/'config.toml')
shutil.copy2(M/'tools/python-print-108/bench.py',R/'bench.py');shutil.copy2(M/'tools/python-print-108/config.json',R/'benchmark-config.json');shutil.copy2(M/'build/snapshot-pool/release/vmm-task',R/'vmm-task')
manifest={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [M/'build/snapshot-pool/release/vmm-task',M/'deploy/fork/bin/cloud-hypervisor',M/'deploy/fork/bin/sandboxer',M/'tools/python-print-108/bench.py']};(R/'binary-and-bench-hashes.json').write_text(json.dumps(manifest,indent=2))
f=measurements['stream']['comparison']['kuasar-fork'];m=measurements['stream']['comparison']['kuasar-mlink'];delta=(1-f['median_ms']/m['median_ms'])*100
lines=['108 real Python startup optimization','',f"Final fork median/max: {f['median_ms']:.3f}/{f['max_ms']:.3f} ms.",f"Contemporaneous mlink median/max: {m['median_ms']:.3f}/{m['max_ms']:.3f} ms.",f"Fork median is {delta:.2f}% lower in this 10-sample run.",'','Protocol:','- Same unchanged python-print-108 benchmark and fixed OCI digest sha256:2fe5997d249a808b8eeea52c58a1dbffbba28754dc11699ef5c029f2d818ce79.','- Fresh /usr/local/bin/python3 -c \'import sys; print(sys.argv[1], flush=True)\' READY_<new uuid> each request. Interpreter starts inside the timer.','- Start: Sandbox.create / ttctl start. End: client receives stdout marker (E2B callback / streamed CLI stdout). Exit status and destruction verified afterward.','- Five alternating rounds of two concurrent requests: exactly 10 per product per variant. No discarded samples or reruns. All first attempts succeeded.','- 1 vCPU, 2048 MiB, 64 generic slots. Existing wrappers remain SDK bash -l -c versus mlink sh -c; both exec identical Python argv.','- Uses prepared-pool sandbox creation, not the latency of immediately forking a live user parent. Live-parent fork remains supported and was separately validated.','- Host shared with other work. No changes to other users, mlink, global CPU settings, client benchmark or application image.','- Prior image audit verified all 1263 Python payload files equal between both imported images; image files/digests were not changed.','','All rounds:','version              fork median/max ms      mlink median/max ms']
for n,d in measurements.items():
 a=d['comparison']['kuasar-fork'];b=d['comparison']['kuasar-mlink'];lines.append(f"{n:20} {a['median_ms']:8.3f}/{a['max_ms']:8.3f}     {b['median_ms']:8.3f}/{b['max_ms']:8.3f}")
lines+=['','Phase medians (different distributions; do not sum these medians):','version             create ms  command->client print ms   guest spawn ms   guest first-stdout ms   guest exit ms']
for n,d in measurements.items():
 g=d['guest_medians_us'];lines.append(f"{n:20} {d['create_median_ms']:8.3f} {d['command_to_print_median_ms']:15.3f} {g['spawn_us']/1000:18.3f} {g['first_stdout_us']/1000:20.3f} {g['exit_us']/1000:15.3f}")
lines+=['','Interpretation:', '- Baseline process spawn was only ~1.9 ms; most execution time elapsed before the first byte. Separate -X importtime diagnostics found encodings startup around 15.7 ms for fork and 17.4 ms for mlink, including aliases around 11 ms. These are diagnostic samples, not the formal median.', '- Both image payloads have no .pyc files. Only file bytes are warmed; Python parsing/compilation/import initialization still happen on every new interpreter.', '- mlink streams stdout. Fork previously buffered until all pipes closed and the process exited (~2.7 ms after first stdout for this Python command). New native ttrpc streaming sends PID, stdout/stderr chunks and final exit independently to the existing E2B Connect stream.', '- Full request median also includes a large creation-stage change, although creation code was not optimized in this task. Do not attribute the entire ~32 ms end-to-end change to Python: command-to-client-print median decreased ~10.7 ms; creation/scheduling/cache variation accounts for the rest. Ten samples do not establish stable production tail percentiles.', '', 'Implementation and invariants:', '- Optional catalog startup_read_files: <=32 absolute image paths, <=64 MiB/file, <=128 MiB total; trusted static busybox performs chroot-bounded read-only reads before immutable template capture. No Python command, .pyc creation, interpreter process or Python heap is prepared.', '- Template metadata records completed read hints, bytes and time. The generic VM pool is still shared across images; hints do not create per-image VM pools.', '- Existing token/lifecycle, entropy, network identity and persistence barriers remain. Claim still restores MAP_PRIVATE CoW RAM, without copying all RAM per sandbox.', '- Streaming output uses a bounded 16 x 4 KiB channel. After disconnect, the worker drains output without accumulating it and reaps the finite child; the transport itself is released. The same host lifecycle operation guard protects execution through exit.', '- Unary ExecVMProcess remains available. This deployment updated the guest agent together with the E2B adapter for the new streaming RPC.','','Preparation and resources:',f"- Read-only startup cache: {prep['startup_cache']['bytes']} bytes ({prep['startup_cache']['bytes']/1024**2:.3f} MiB), {prep['startup_cache']['elapsed_ms']:.3f} ms once per file template. This is NOT hidden inside the request timer.",f"- Service start to ready/listening: {startup/1000:.3f} s. Template preparation {prep['preparation_ms']:.3f} ms includes the read cache; host memory-file warmup {prep['warmup_ms']:.3f} ms; metadata staging {prep['metadata_stage_ms']:.3f} ms.",f"- Refill actual work median/max {refill['elapsed_ms']['median_ms']:.3f}/{refill['elapsed_ms']['max_ms']:.3f} ms; replacement with the preexisting 1000 ms delay {refill['replacement_ms']['median_ms']:.3f}/{refill['replacement_ms']['max_ms']:.3f} ms."]
for n,d in resources.items():lines.append(f"- {n}: {d['Pss']/1024:.2f} MiB PSS, {d['fds']} host FDs.")
v=validation['validation'];st=validation['stream-validation']
lines+=['','Validation:', '- Before first Python execution: 0 guest Python processes and 0 .pyc files, audited with busybox only.','- Real Python print followed by 1 second of continued execution: output arrived '+f"{st['output_precedes_exit_ms']:.2f} ms before completion.",f"- stderr/nonzero exit preserved; disconnect test guest FDs {st['guest_fd_before']} -> {st['guest_fd_after_disconnect']}.",f"- Live-parent fork: same process PID/nonce, {v['shared_sampled_pfns']} sampled shared PFNs, 16 MiB buffers diverged to 20/30; independent file writes.",'- Parent-first and child-first deletion; grandchild after parent deletion; independent MAC/IP/CID and bidirectional HTTP; parent TCP survives child reset/deletion all passed.','- Corrupt template binding rejected and slot reclaimed. Final ready=64, assigned=0; FDs return to 2239.','- 77 Python regression tests passed; native streaming, disconnect/reap and unary structured-exit tests passed.','', 'Evidence: measurements.json, raw per-sample JSON, phase logs, import diagnostics, preparation/FD/CoW/stream validation records, source/, changes.patch and binary-and-bench-hashes.json.']
(R/'REPORT.txt').write_text('\n'.join(lines)+'\n');print('\n'.join(lines[:6]));print('startup_ms',startup,'refill',refill)
